import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, vec3, uv } from 'three/tsl';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;
  const root = new Group();
  const timelines = [];
  const primitiveResults = [];
  let disposed = false;
  let loadedTexture = null;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const gradientStops =
    config.intent?.visualSpec?.gradientStops ??
    [colors.surface, colors.ink, colors.surface];

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = smoothstep(0.0, 1.0, uv().y);
  const firstGradient = mix(
    vec3(gradientStops[0]),
    vec3(gradientStops[1] ?? gradientStops[0]),
    backdropY
  );
  backdropMaterial.colorNode = mix(
    firstGradient,
    vec3(gradientStops[2] ?? gradientStops[1] ?? gradientStops[0]),
    smoothstep(0.48, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const shadowGeometry = new PlaneGeometry(3.25, 1.9);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.03, -0.55);
  shadow.scale.set(1.08, 0.88, 1);
  root.add(shadow);

  const cardGeometry = new PlaneGeometry(3.2, 2.0);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.paper
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, 0);
  root.add(card);

  const foregroundGeometry = new PlaneGeometry(0.055, 1.7);
  const foregroundMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.9
  });
  const foreground = new Mesh(foregroundGeometry, foregroundMaterial);
  foreground.position.set(-1.48, -0.02, 0.12);
  root.add(foreground);

  const grainUrl = config.imageUrl;
  if (grainUrl) {
    ctx.textureLoader.loadTexture(grainUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      loadedTexture = texture;

      const imageWidth = texture.image?.width || config.atlasWidth || 512;
      const imageHeight = texture.image?.height || config.atlasHeight || 320;
      const source = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      texture.offset.set(
        source.x / imageWidth,
        1 - (source.y + source.height) / imageHeight
      );
      texture.repeat.set(
        source.width / imageWidth,
        source.height / imageHeight
      );
      texture.needsUpdate = true;

      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  card.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) card.quaternion.copy(camera.quaternion);
  };

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    loadedTexture?.dispose?.();

    backdropGeometry.dispose();
    shadowGeometry.dispose();
    cardGeometry.dispose();
    foregroundGeometry.dispose();

    backdropMaterial.dispose();
    shadowMaterial.dispose();
    cardMaterial.dispose();
    foregroundMaterial.dispose();

    root.clear();
  };

  return root;
}

export default createNode;
